'use client'
import { fetchIngredientPricing } from "../../util/actions";
import IngredientDetails from "../../types/models/IngredientDetails";
import InputField from "@/app/components/Elements/login/InputField";
import { useEffect, useState } from "react";

const getAllIngredients = async () => {
  const response = await fetchIngredientPricing(1);
  return response;
}

export default function MarketContainer() {
    const [ingredients, setIngredients] = useState<IngredientDetails[]>([]);
    const [searchTerm, setSearchTerm] = useState<string>("");

    useEffect(() => {
        const fetchIngredients = async () => {
            const ing = await getAllIngredients();
            setIngredients(ing);
        };
        fetchIngredients();
    }, []);

    const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setSearchTerm(e.target.value);
    }

    return (
        <div className="flex flex-col items-center">
            <h1 className="text-2xl font-bold my-4">Market</h1>
            <div className="flex w-full justify-start">
                <InputField 
                    id="input"
                    type="text"
                    placeholder="Search..."
                    error={searchTerm ? "" : "Please enter a search term."}
                    value={searchTerm}
                    onChange={handleSearchChange}
                />
            </div>
            {/* Additional content can be added below this level */}
            <div className="mt-4">
                {/* Placeholder for more content */}
                {ingredients.length > 0 ? (
                    <ul>
                        {ingredients.map((ingredient) => (
                            <li key={ingredient.ingredientId}>{ingredient.ingredientName}</li>
                        ))}
                    </ul>
                ) : (
                    <p>No ingredients found.</p>
                )}
            </div>
        </div>
    );
}
